import{_ as s,a0 as r,w as a,s as u,I as n,x as l,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"開源軟件的易用性 | LCTT x X-CMD","titleTemplate":false,"description":"開源軟件的易用性 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源軟件的易用性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源軟件的易用性 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Usability and Open Source","title":"開源軟件的易用性","tag":"201403","desc":""},"relativePath":"201403/Usability and Open Source.md","filePath":"[post].md"}'),p={name:"201403/Usability and Open Source.md"};function d(m,t,f,b,x,T){const o=r("Link");return a(),u("div",null,[t[15]||(t[15]=n("h1",{id:"開源軟件的易用性",tabindex:"-1"},[l("開源軟件的易用性 "),n("a",{class:"header-anchor",href:"#開源軟件的易用性","aria-label":"Permalink to “開源軟件的易用性”"},"​")],-1)),n("p",null,[e(o,{href:"http://opensource-usability.blogspot.com/"},{default:i(()=>[...t[0]||(t[0]=[l("Jim Hall",-1)])]),_:1}),t[2]||(t[2]=l(" 在 Linux Journal 網站上發表了一篇精彩的",-1)),e(o,{href:"http://www.linuxjournal.com/content/its-about-user-applying-usability-open-source-software"},{default:i(()=>[...t[1]||(t[1]=[l("文章",-1)])]),_:1}),t[3]||(t[3]=l("，是關於開源軟件的“易用性”的。在開源項目中，軟件的“友好性”往往被敷衍處理，甚至會被完全忽略。另一方面，人們經常將“易用性”與“美觀”混為一談，他們認為軟件“易於使用”就是要軟件設計得漂亮。開源項目軟件的“易用性”經常被開發者忽略，這可以理解，畢竟開發者肯定知道如何使用他們自己的軟件，並且對開發的軟件的工作環境也瞭如指掌（譯註：舉個生活中的例子，譯者，就是我，想去附近的阿姨家玩，只需要出門左轉右轉過個紅綠燈再過三幢房就到了，因為我對環境瞭如指掌；如果要讓讀者，就是你，找到我阿姨家，估計你要衝過來削我：你 TM 在逗我麼）。開源軟件能很好地滿足開發者自身的需求，但如果想讓你的軟件被更多人使用，你就需要在“易用性”方面下大功夫。",-1))]),t[16]||(t[16]=n("p",null,"在 Linux Journal 上的這篇文章裏面，Hall 介紹了他與幾個大學生一起做了一個小小的易用性測試，這些學生都是 Windows 用户，並且對電腦都不怎麼熟悉。他們被要求使用裝有 Fedora 17 的筆記本，並且要求使用一系列軟件，像 Gedit、 Firefox 和 Nautilus，Hall 在一旁觀察，並做一些記錄。結果顯示這些用户能夠使用這些軟件的基本功能，但對於軟件的一些高級功能，他們就束手無策了。他們能夠在不需要任何提示的情況下使用火狐上網，但當要求他們改變 Gedit 的默認字體，或使用 Nautilus 為一個文件建立書籤時，他們就不知道怎麼做了。",-1)),t[17]||(t[17]=n("p",null,"Hall 做的這項實驗對開發者來説是非常有意義的。你永遠都想不到用户會將你的軟件用在什麼地方，並且對於你覺得一目瞭然的特性，就跟長在臉上的鼻子一樣清楚明瞭的特性，在用户眼裏可能就是那麼難以理解。我在讀研的時候，就做過一個“軟件易用性”實驗，實驗的道具是一款名叫“Silverback”的商業軟件，它會調用電腦內置攝像頭來拍攝用户的臉部表情。當用户坐下來完成我們佈置的任務時，我們中的一個人會坐在用户旁邊並做一些記錄，實驗結束後我們會回頭看錄像，記錄用户鼠標點擊次數、用户完成每個任務需要的時間，以及他們是否能完成所有任務。記錄用户臉部表情非常有用，特別是配合用户做任務時實驗人員寫下來的實驗記錄的時候。筆記上有一條“在第６個步驟有些迷惑”的記錄，用户臉部表情與這個記錄保持一致，這能顯示用户在什麼時候感覺遇到挫折了。",-1)),t[18]||(t[18]=n("p",null,"如果你沒有參與過開源社區，這是一個很好的起點。“易用性”不好，就是一個 bug，與軟件其它 bug 一樣，都需要解決。一個軟件如果不能按用户的思路來處理用户的問題，這就是一個 bug。如果你是一個開發者，幫自己一個忙，坐在一個資深的軟件使用者旁邊，讓他用用你的軟件。不要指點，不要提醒，不要告訴他需要按什麼按鍵，就讓他自己把玩，自己發現軟件的用處（就讓他往死裏吐槽）。也許你能對你的軟件有更深一層的瞭解。如果你覺得了解自己的軟件，試試讓其他人玩玩吧。",-1)),t[19]||(t[19]=n("hr",null,null,-1)),n("p",null,[t[5]||(t[5]=l("via: ",-1)),e(o,{href:"http://ostatic.com/blog/usability-and-open-source"},{default:i(()=>[...t[4]||(t[4]=[l("http://ostatic.com/blog/usability-and-open-source",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=l("譯者：",-1)),e(o,{href:"https://github.com/bazz2"},{default:i(()=>[...t[6]||(t[6]=[l("bazz2",-1)])]),_:1}),t[9]||(t[9]=l(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[7]||(t[7]=[l("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=l("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[l("LCTT",-1)])]),_:1}),t[13]||(t[13]=l(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[l("Linux中國",-1)])]),_:1}),t[14]||(t[14]=l(" 榮譽推出",-1))])])}const y=s(p,[["render",d]]);export{L as __pageData,y as default};
